#include <bits/stdc++.h>
#define err(args...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using ll = long long;
const int N = 10;
string g[N];
int n_scientists[N][N] = {};
int n_rescue[N][N] = {};
int infect_time[N][N] = {};
int di[] = {-1, 1, 0, 0};
int dj[] = {0, 0, -1, 1};
int reach_time[N][N][N][N] = {};
const int FLOW_N = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj[FLOW_N+1];
int c[FLOW_N+1][FLOW_N+1], f[FLOW_N+1][FLOW_N+1], adj_ptr[FLOW_N+1], d[FLOW_N+1], p[FLOW_N+1];

bool build_level_graph(int s, int t) {
    memset(d, -1, sizeof d);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(int v : adj[u]) {
            if(c[u][v] - f[u][v] > 0 && d[v] == -1) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
    return d[t] != -1;
}

bool dfs_path(int u, int t) {
    if(u == t) return true;
    for(int& i = adj_ptr[u]; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if(d[v] == d[u] + 1 && c[u][v] - f[u][v] > 0 && dfs_path(v, t)) {
            p[v] = u;
            return true;
        }
    }
    return false;
}

bool find_augmenting_path(int s, int t) {
    memset(p, -1, sizeof p);
    p[s] = 0;
    return dfs_path(s, t);
}

void initialize_flow() {
    memset(c, 0, sizeof c);
    memset(f, 0, sizeof f);
}

void add_edge(int u, int v, int cap) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    c[u][v] += cap;
}

int compute_max_flow(int s, int t) {
    int total_flow = 0;
    while(build_level_graph(s, t)) {
        memset(adj_ptr, 0, sizeof adj_ptr);
        while(find_augmenting_path(s, t)) {
            int flow_cap = INF;
            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                flow_cap = min(flow_cap, c[u][v] - f[u][v]);
            }
            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                f[u][v] += flow_cap;
                f[v][u] -= flow_cap;
            }
            total_flow += flow_cap;
        }
    }
    return total_flow;
}

int node_id(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    string line;
    pair<int, int> explosion;
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] == 'Y') {
                g[i][j] = 'Y';
            } else if(line[j] == 'Z') {
                g[i][j] = 'Z';
                explosion = {i,j};
            } else {
                g[i][j] = '.';
                n_scientists[i][j] += line[j] - '0';
            }
        }
    }
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] != 'Y' && line[j] != 'Z') {
                n_rescue[i][j] += line[j] - '0';
            }
        }
    }
    memset(infect_time, -1, sizeof infect_time);
    infect_time[explosion.first][explosion.second] = 0;
    queue<pair<int,int>> q;
    q.push(explosion);
    while(!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for(int d=0; d<4; d++) {
            int ni = i + di[d], nj = j + dj[d];
            if(0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.' && infect_time[ni][nj] == -1) {
                infect_time[ni][nj] = infect_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
    memset(reach_time, -1, sizeof reach_time);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(g[i][j] == '.') {
                reach_time[i][j][i][j] = 0;
                queue<pair<int,int>> q2;
                q2.push({i,j});
                while(!q2.empty()) {
                    int ii = q2.front().first, jj = q2.front().second;
                    q2.pop();
                    if(infect_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                        for(int d=0; d<4; d++) {
                            int ni = ii + di[d], nj = jj + dj[d];
                            if(0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.' &&
                               (infect_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj]) &&
                               reach_time[i][j][ni][nj] == -1) {
                                reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                q2.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }
    int src = 2 * n * n, sink = 2 * n * n + 1;
    initialize_flow();
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(n_scientists[i][j]) {
                add_edge(src, node_id(n, i, j, false), n_scientists[i][j]);
            }
            if(n_rescue[i][j]) {
                add_edge(node_id(n, i, j, true), sink, n_rescue[i][j]);
            }
            for(int ii=0; ii<n; ii++) {
                for(int jj=0; jj<n; jj++) {
                    if(0 <= reach_time[i][j][ii][jj] && reach_time[i][j][ii][jj] <= t) {
                        add_edge(node_id(n, i, j, false), node_id(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }
    cout << compute_max_flow(src, sink) << endl;
    return 0;
}
